 draftingUI?.invalidate();impactUI?.invalidate();templatesUI?.invalidate();resolutionUI?.invalidate();intakeUI?.invalidate();draftingUI=null;impactUI=null;templatesUI=null;resolutionUI=null;intakeUI=null;guideUI=null;clearTimeout(pollTimer);clearTimeout(toast.timer);++routeGeneration;
 if(modal.open)modal.close();modal.replaceChildren();toastEl.textContent='';
