async function api(path,{method='GET',data}={}){
 const requestSession=S.session;
 let r;
 const assertSession=()=>{if(requestSession!==S.session){const e=new Error('This response belongs to an earlier session.');e.staleSession=true;throw e;}};
 const recovery=method==='GET'?'Check your connection and try loading this view again.':'Your action may have been saved. Reload the view and check the records before submitting it again.';
 try{r=await fetch(path,{method,credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&requestSession?{'X-CSRF-Token':requestSession.csrfToken}:{})},...(data?{body:JSON.stringify(data)}:{})});}
 catch{assertSession();throw new Error('Qivvera could not be reached. '+recovery);}
 assertSession();
 if(r.status===401&&!(path==='/api/session'&&method==='POST')&&requestSession){
   clearSessionView();
   login('Your session ended. Sign in again to continue. Your saved records are retained.');
   const e=new Error('Your session ended. Please sign in again.');e.status=401;e.sessionExpired=true;throw e;
 }
 let b;try{b=await r.json();}catch{assertSession();const e=new Error('Qivvera returned an unreadable response. '+recovery);e.status=r.status;throw e;}
 assertSession();
 if(!r.ok){
  let message=typeof b?.message==='string'?b.message:'This request could not be completed.';
  if(r.status===403)message+=' Check your role and reload the view before trying again.';
  if(r.status>=500)message+=' If this continues, contact your workspace operator using Support.';
  const reference=typeof b?.requestId==='string'&&/^[0-9a-f-]{36}$/i.test(b.requestId)?b.requestId:null;
  const e=new Error(message+(reference?' Request reference: '+reference+'.':''));e.status=r.status;e.code=b?.error;e.requestId=reference;throw e;
 }return b;
}
async function refresh(){const session=S.session,workspace=await api('/api/workspace');if(session===S.session)S.workspace=workspace;}
function login(error=''){
 root.innerHTML=`<main class="login-layout" id="main"><section class="login-story"><div class="brand">${logoSvg}</div><div class="login-message"><div class="eyebrow">Independent Change Assurance</div><h1>Confidence needs<br>more than a<br>green pipeline.</h1><p>Start with the change. Establish what must be true. Keep the evidence — and the uncertainty — visible.</p></div><div class="chain">CHANGE &nbsp;→&nbsp; OBLIGATIONS &nbsp;→&nbsp; EVIDENCE &nbsp;→&nbsp; GAPS &nbsp;→&nbsp; DISPOSITION</div></section><section class="login-panel"><form id="login-form"><div class="eyebrow">Your review workspace</div><h2>Welcome to Qivvera</h2><p class="sub">Sign in to organize applications, changes, and assurance obligations.</p><div class="form-error" role="alert">${h(error)}</div><div class="form-field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="username" required></div><div class="form-field"><label for="password">Password</label><div class="input-with-eye"><input id="password" name="password" type="password" autocomplete="current-password" maxlength="256" required><button type="button" class="eye-btn" id="toggle-password" aria-label="Show password">Show</button></div></div><button class="button primary" type="submit">Open workspace &nbsp;→</button><div class="login-note">Increment 10 · Assurance workflow improvements<br>Review requirements, run supported checks, and inspect scope-bound conclusions. Use non-sensitive review data. For access or password help, contact the workspace operator who provided your account.</div></form></section></main>`;
 document.querySelector('#toggle-password').addEventListener('click',e=>{const p=document.querySelector('#password');p.type=p.type==='password'?'text':'password';e.currentTarget.textContent=p.type==='password'?'Show':'Hide';e.currentTarget.setAttribute('aria-label',p.type==='password'?'Show password':'Hide password');});
 document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;b.textContent='Signing in…';try{S.session=await api('/api/session',{method:'POST',data:Object.fromEntries(new FormData(f))});await refresh();await route();}catch(err){if(!err.staleSession&&!err.sessionExpired)f.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;b.textContent='Open workspace →';}});
}
function shell(content,active='overview',label='Workspace'){
 renderedGeneration=routeGeneration;
 const email=S.session.email;
 root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${logoSvg}</div><div class="label">Assurance workspace</div><nav class="nav" aria-label="Main navigation">${[['overview','Workspace'],['applications','Applications'],['changes','Changes'],...(S.workspace?.capabilities.resolutionWorkflow?[["resolutions","Resolutions"]]:[]),...(S.workspace?.capabilities.githubIntake?[["intake","GitHub intake"]]:[]),...(S.workspace?.capabilities.verificationTemplates?[["verification-templates","Verification templates"]]:[]),['activity','Activity'],['guide','Guide'],['support','Support']].map(([id,t])=>`<a href="#/${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}${t}</a>`).join('')}</nav><div class="sidebar-foot"><span class="workspace-tag">REVIEW WORKSPACE</span><p>Independent assurance.<br>Explicit uncertainty.</p><p>Release ${h(S.workspace?.release??'0.11.0')} · ${h(S.workspace?.storage==='postgres'?'PostgreSQL':'Local review')}</p></div></aside><div class="right"><header class="topbar"><div class="breadcrumb">Qivvera &nbsp; / &nbsp; <strong>${h(label)}</strong></div><div class="identity"><div class="avatar">${h(email.slice(0,2).toUpperCase())}</div><div class="email"><span>${h(email)}</span><small>${h((S.session.roles??[]).map(x=>x==='POLICY_AUTHORITY'?'Policy authority':x==='AUTHOR'?'Author':'Viewer').join(' · '))}</small></div><button class="link-button" data-action="logout">Sign out</button></div></header><main id="main" class="main">${content}<footer class="footer"><span>Qivvera · Independent Change Assurance</span><span>Acceptance is not verification. Assessments are bound to their declared scope.</span></footer></main></div></div>`;
}
const note=()=>`<div class="notice"><span class="symbol">i</span><span><strong>Requirements, evidence, and decisions stay distinct.</strong> Accepting a requirement does not establish software correctness. Run a supported assessment and inspect its declared scope.</span></div>`;
function changeRows(changes){return changes.length?changes.map(c=>`<div class="row"><div><a href="#/changes/${h(c.id)}">${h(c.title)}</a><span class="muted">${h(S.workspace.applications.find(a=>a.id===c.applicationId)?.name??'Application')} &nbsp;·&nbsp; Revision ${h(short(c.sourceRevision))}</span></div>${badge(c.assuranceError?'ASSURANCE UNAVAILABLE':c.disposition??(c.latestAssessment?.applicability==='STALE_INPUTS'?'REASSESSMENT REQUIRED':c.assessmentStatus?.replaceAll('_',' ')??'NOT ASSESSED'),c.assuranceError?'finding-gap':resultKind(c.disposition))}</div>`).join(''):`<div class="empty"><div class="empty-icon">↗</div><h3>No changes registered yet</h3><p>Register an application, then describe the change you want to understand.</p><button class="button" data-action="new-change" ${S.workspace.applications.length&&can('AUTHOR')?'':'disabled'}>Create a change</button></div>`;}
function activityRows(items){return items.length?items.map(a=>`<div class="activity"><strong>${h(({APPLICATION_CREATED:'Application registered',CHANGE_CREATED:'Change created',OBLIGATION_PROPOSED:'Candidate obligation added',OBLIGATION_UPDATED:'Candidate draft updated'})[a.action]??a.action)}</strong><p>${h(a.action==='OBLIGATION_UPDATED'?'Previous draft retained in activity record.':a.detail)}</p><p>${h(date(a.createdAt))} · ${h(a.actor)}</p></div>`).join(''):`<p class="small muted">Your saved actions will appear here. No activity has been recorded yet.</p>`;}
function gettingStarted(){
 const author=can('AUTHOR'),authority=can('POLICY_AUTHORITY');
 const roleText=author&&authority?'You can author changes and record authority decisions. Independent review still requires an eligible different reviewer when you contributed to the requirement.':author?'You can register applications, describe changes, propose requirements and request assessments. A Policy Authority reviews requirements and approves verification plans.':authority?'You can review submitted requirements, approve verification plans and assess proposed corrections. An Author records the application, change and candidate requirements.':'You can inspect changes, decisions, evidence and history. Ask a named Author or Policy Authority to make changes; Viewer access does not allow saving decisions.';
 const start=!S.workspace.applications.length?(author?'Register your first application, then create a change. A repository reference alone does not connect its source.':'No application has been registered. Ask an Author to prepare the first change; the guide explains what to look for.'):!S.workspace.changes.length?(author?'Create a change for a registered application and record the outcome you expect.':'No change has been registered. Ask an Author to describe the first change, then open it here.'):'Open a change to see its current revision, next step and any outstanding findings.';
 return `<section class="panel getting-started" aria-labelledby="getting-started-title"><div class="panel-head"><div><span class="eyebrow">Getting started</span><h2 id="getting-started-title">Start with your role</h2></div><a class="button" href="#/guide">Read the product guide</a></div><div class="panel-body"><p>${h(roleText)}</p><p><strong>Your starting point:</strong> ${h(start)}</p><p class="small muted">Use synthetic review data and operator-approved test targets. You can always return to Guide for terminology, supported checks and the full workflow.</p></div></section>`;
}
function nextStep(){
 const c=S.change,ctx=S.assuranceContext,latest=S.runs[0],author=can('AUTHOR'),authority=can('POLICY_AUTHORITY');
 const required=c.obligations.filter(o=>o.reviewStatus!=='REJECTED');
 const draft=required.some(o=>['DRAFT','CLARIFICATION_REQUIRED'].includes(o.reviewStatus));
 const pending=required.some(o=>o.reviewStatus==='IN_REVIEW');
 let message,action;
 const tab=(name,label)=>`<button class="link-button" data-action="tab" data-tab="${name}">${label}</button>`;
 if(!c.isCurrentRevision){message='You are viewing an earlier revision. Its decisions and evidence are retained for comparison; they do not establish the current revision’s result.';action=`<a href="#/changes/${h(c.id)}">Open current revision →</a>`;}
 else if(S.assuranceError){message='Assessment details could not be loaded. Refresh before relying on a displayed result. If the problem continues, use Support to give the workspace operator a request reference.';action='<button class="link-button" data-action="refresh-assurance">Reload assessment details</button>';}
 else if(latest&&['QUEUED','RUNNING'].includes(latest.status)){message=latest.status==='QUEUED'?'Your assessment is queued. Keep this view open or refresh it to see progress. If it remains queued, ask the operator to check the separate worker; queuing does not confirm that the worker is available.':'Your assessment is running the approved checks. Wait for completion before interpreting evidence. Cancelling stops result acceptance; it cannot undo test operations already sent.';action=tab('assurance','View assessment progress');}
 else if(latest?.applicability==='CURRENT'&&latest.status==='COMPLETED'&&!latest.disposition){message='The completed record does not have an accepted disposition. Inspect its evidence integrity and ask the operator to investigate; a new passing run must not hide missing or damaged earlier evidence.';action=tab('evidence','Inspect evidence');}
 else if(latest?.applicability==='CURRENT'&&latest.disposition==='NOT_READY'){message='A required obligation has a valid violation. Inspect the expected and observed behaviour, record the correction, and obtain fresh evidence. Closing a resolution item does not change the original result.';action=tab('evidence','Inspect the finding');}
 else if(latest?.applicability==='CURRENT'&&latest.disposition==='INDETERMINATE'){message='There is not enough evidence for every required obligation. Inspect the findings to distinguish a requirement-review gap, an unsupported mapping or an execution problem. An unknown result must remain visible.';action=tab('evidence','Inspect the gaps');}
 else if(latest?.applicability==='CURRENT'&&latest.disposition==='READY'){message='Every non-rejected declared obligation is supported within this assessment’s frozen scope. Read the evidence and exclusions before making a separate release decision. A new revision or changed inputs requires fresh assessment.';action=tab('evidence','Review the assurance case');}
 else if(!required.length){message=author?'Record at least one applicable obligation and its source. Rejected candidates remain in history; an empty scope does not prove readiness.':'Ask an Author to record the applicable obligations and their sources. Requirement acceptance and verification will follow separately.';action=tab('obligations','Open obligations');}
 else if(draft){message=author?'Complete draft requirements, including their sources and versions, then request review. Clarification requests need an updated draft before resubmission.':'An Author must complete or clarify the remaining drafts and request review. A draft is not an accepted requirement.';action=tab('obligations','Review obligation progress');}
 else if(pending){message=authority?'Review the submitted obligations and record why each applies, needs clarification or should be rejected. In independent mode, your own contributions need a different eligible reviewer.':'Requirements are awaiting a Policy Authority’s decision. You can inspect their sources and review history while waiting.';action=tab('obligations','Open pending requirements');}
 else if(!ctx){message='The workflow can retain requirements, but assurance execution is not available in this workspace. Ask the operator to enable and verify the approved test setup.';action='<a href="#/support">Open workspace support →</a>';}
 else if(!ctx.targets.length){message='No approved test target matches this application and its full declared source revision. Ask the operator to configure the matching test target before a plan can be approved.';action=tab('assurance','Inspect assurance setup');}
 else if(!ctx.plan?.current){message=authority?'Approve a current verification plan. Map supported checks only to requirements they actually establish; every other non-rejected obligation remains a visible gap.':'A Policy Authority must approve a current verification plan for these inputs. Earlier plans and results remain in history.';action=tab('assurance','Open verification plan');}
 else if(latest&&['FAILED','CANCELLED'].includes(latest.status)){message='The previous attempt produced no accepted disposition. Inspect the run and resolve its cause before explicitly requesting another assessment. Previous target operations may already have happened.';action=tab('assurance','Inspect the previous run');}
 else{message=author||authority?'The current plan can be submitted to the separate worker. Run assurance, then inspect every finding and the scope limitations. Unmapped obligations will remain gaps.':'A current plan is available. Ask an Author or Policy Authority to request the assessment, then inspect the resulting evidence.';action=tab('assurance','Open assurance');}
 return `<section class="next-step" aria-labelledby="next-step-title"><div><h2 id="next-step-title">What to do next</h2><p>${h(message)}</p></div><div class="actions">${action}<a class="small" href="#/guide">Workflow guide</a></div></section>`;
}
function overview(){const w=S.workspace;
 shell(`<div class="heading"><div><div class="eyebrow">Independent Change Assurance</div><h1>Your assurance workspace</h1><p class="sub">A clear starting point for every consequential change.</p></div><div class="actions"><button class="button" data-action="new-application" ${can('AUTHOR')?'':'disabled'}>+ Register application</button></div></div>${note()}${gettingStarted()}<div class="stats"><div class="stat"><span class="stat-label">Registered applications</span><span class="value">${w.applications.length}</span><small>Owned application records</small></div><div class="stat"><span class="stat-label">Registered changes</span><span class="value">${w.changes.length}</span><small>Each revision has its own assessment</small></div><div class="stat"><span class="stat-label">Changes with current evidence</span><span class="value">${w.changes.filter(c=>c.disposition).length}</span><small>Open a change to inspect scope and gaps</small></div></div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Changes to understand</h2><p>Start with intent. Keep the source revision explicit.</p></div><a class="small" href="#/changes">View all →</a></div>${changeRows(w.changes.slice(0,5))}</section><section class="panel"><div class="panel-head"><h2>Build your assurance context</h2></div><div class="panel-body"><ol class="checklist"><li><span class="step ${w.applications.length?'done':''}">${w.applications.length?'✓':'1'}</span><div><strong>Register an application</strong><p>Name the system and add its repository reference.</p></div></li><li><span class="step ${w.changes.length?'done':''}">${w.changes.length?'✓':'2'}</span><div><strong>Describe the change</strong><p>Capture the intended outcome and declared revision.</p></div></li><li><span class="step ${w.changes.some(c=>c.obligationCount>0)?'done':''}">${w.changes.some(c=>c.obligationCount>0)?'✓':'3'}</span><div><strong>Propose obligations</strong><p>Record what must be true. Nothing becomes authoritative automatically.</p></div></li></ol><div class="inline-note">An authorized mapping defines the supported check. A separate worker collects actual observations.</div></div></section></div><section class="panel"><div class="panel-head"><h2>Recent activity</h2><a class="small" href="#/activity">Open activity →</a></div><div class="panel-body">${activityRows(w.activity.slice(0,3))}</div></section>`);
}
function applications(){shell(`<div class="heading"><div><div class="eyebrow">Application registry</div><h1>Applications</h1><p class="sub">The systems whose changes you will assure.</p></div><div class="actions"><button class="button" data-action="new-application" ${can('AUTHOR')?'':'disabled'}>+ Register application</button><button class="button primary" data-action="new-change" ${S.workspace.applications.length&&can('AUTHOR')?'':'disabled'}>+ New change</button></div></div>${S.workspace.applications.length?`<div class="app-grid">${S.workspace.applications.map(a=>`<a class="app-card" href="#/applications/${h(a.id)}"><div class="card-top"><div class="app-icon">${h(a.name.slice(0,2).toUpperCase())}</div>${badge('REGISTERED')}</div><h2>${h(a.name)}</h2><p>${h(a.description||'No description yet.')}</p><div class="app-meta"><span>${S.workspace.changes.filter(c=>c.applicationId===a.id).length} changes</span><span>Source not connected →</span></div></a>`).join('')}</div>`:`<section class="panel"><div class="empty"><div class="empty-icon">▦</div><h2>Give your first application a home</h2><p>Registering an application does not connect to its source or fetch its code.</p><button class="button primary" data-action="new-application" ${can('AUTHOR')?'':'disabled'}>Register application</button></div></section>`}`,'applications','Applications');}
function application(id){const a=S.workspace.applications.find(x=>x.id===id);if(!a)return errorPage('Application not found.');shell(`<a class="back" href="#/applications">← Applications</a><div class="heading"><div><div class="eyebrow">Registered application</div><h1>${h(a.name)}</h1><p class="sub">${h(a.description||'No description supplied.')}</p></div><button class="button primary" data-action="new-change" data-app="${h(a.id)}" ${can('AUTHOR')?'':'disabled'}>+ New change</button></div><section class="panel"><div class="panel-body details"><div><span class="field-label">Repository reference</span><div class="detail-value">${h(a.repositoryUrl||'Not supplied')}</div><div class="small muted">Reference only. Source access has not been verified.</div></div><div><span class="field-label">Registered</span><div class="detail-value">${h(date(a.createdAt))}</div></div></div></section><section class="panel" id="app-pulls"><div class="panel-head"><div><h2>Pull requests</h2><p>Open pull requests from the operator-connected repository. Listed for context only.</p></div>${S.workspace.capabilities.githubIntake?'<button class="link-button" data-action="refresh-pulls">Refresh</button>':''}</div><div class="panel-body" id="app-pulls-body">${S.workspace.capabilities.githubIntake?'<p class="muted">Loading pull requests…</p>':pullsNotConnected()}</div></section>${S.workspace.capabilities.githubWebhooks?'<section class="panel" id="app-events"><div class="panel-head"><div><h2>PR activity from GitHub</h2><p>Signed webhook deliveries for this application. Nothing is imported automatically.</p></div><button class="link-button" data-action="refresh-events">Refresh</button></div><div class="panel-body" id="app-events-body"><p class="muted">Loading activity…</p></div></section>':''}<div class="tabs"><button class="active">Changes</button></div><section class="panel">${changeRows(S.workspace.changes.filter(c=>c.applicationId===a.id))}</section>`,'applications',a.name);if(S.workspace.capabilities.githubIntake)loadPulls(a.id);if(S.workspace.capabilities.githubWebhooks)loadSourceEvents(a.id);}
const eventLabel={opened:'Opened',synchronize:'New commits',reopened:'Reopened',ready_for_review:'Ready for review'};
async function loadSourceEvents(appId){
 const active=viewContext(),body=()=>document.querySelector('#app-events-body');
 try{
  const r=await api(`/api/applications/${encodeURIComponent(appId)}/source-events`);
  if(!active()||!body())return;
  body().innerHTML=r.pulls.length?r.pulls.map(p=>`<div class="row"><div><a href="${h(p.url)}" target="_blank" rel="noopener noreferrer">${h(p.repository)} #${h(p.pullNumber)} ${h(p.title)}</a>${p.draft?' '+badge('Draft'):''}<span class="muted">${h(eventLabel[p.action]??p.action)} · <code>${h(p.headSha.slice(0,7))}</code> · ${h(p.headRef)} → ${h(p.baseRef)} · ${h(p.sender)} · ${h(date(p.receivedAt))}</span></div><div>${p.imported?`<a class="button" href="#/changes/${h(p.imported.changeId)}">Open linked change</a>${p.imported.currentHead?' <span class="small muted">Up to date</span>':' <span class="small muted">New commits since import</span>'}`:'<span class="small muted">Not imported</span>'}${can('AUTHOR')&&(!p.imported||!p.imported.currentHead)?` <a class="button primary" href="#/intake/${encodeURIComponent(p.repositoryKey)}/${h(p.pullNumber)}">${p.imported?'Import new commits':'Import'}</a>`:''}</div></div>`).join('')+`<p class="small muted">${h(r.notice)}</p>`:'<p class="muted">No pull-request activity has been received yet.</p><p class="small muted">GitHub sends an event when a pull request is opened, updated, reopened or marked ready for review.</p>';
 }catch(err){if(!active()||err.sessionExpired||err.staleSession||!body())return;body().innerHTML=`<div class="notice warning">${h(err.message)}</div>`;}
}
function pullsNotConnected(){return `<p><strong>No repository is connected.</strong> The repository URL above is stored as a reference only.</p><p class="small muted">To list pull requests here, the workspace operator connects this application's GitHub repository with read access (QIVVERA_GITHUB_INTAKE_ENABLED and QIVVERA_GITHUB_REPOSITORIES_JSON).</p>`;}
async function loadPulls(appId){
 const active=viewContext(),body=()=>document.querySelector('#app-pulls-body');
 try{
  const r=await api(`/api/applications/${encodeURIComponent(appId)}/pull-requests`);
  if(!active()||!body())return;
  if(!r.repositories.length){body().innerHTML=pullsNotConnected();return;}
  body().innerHTML=r.repositories.map(g=>`<div class="pull-group"><div class="field-label">${h(g.repository.owner+'/'+g.repository.repo)}</div>${g.error?`<div class="notice warning">${h(g.error.message)}</div>`:g.pulls.length?g.pulls.map(p=>`<div class="row"><div><a href="${h(p.url)}" target="_blank" rel="noopener noreferrer">#${h(p.number)} ${h(p.title)}</a>${p.draft?' '+badge('Draft'):''}<span class="muted">${h(p.author)} · ${h(p.headRef)} → ${h(p.baseRef)}${p.updatedAt?' · updated '+h(date(p.updatedAt)):''}</span></div><div>${p.imported?`<a class="button" href="#/changes/${h(p.imported.changeId)}">Open linked change</a>${p.imported.currentHead?'':' <span class="small muted">New commits since import</span>'}`:''}${can('AUTHOR')&&(!p.imported||!p.imported.currentHead)?` <a class="button primary" href="#/intake/${encodeURIComponent(g.repository.id)}/${h(p.number)}">${p.imported?'Import new commits':'Import'}</a>`:''}</div></div>`).join(''):'<p class="muted">No open pull requests.</p>'}</div>`).join('')+`<p class="small muted">${h(r.notice)}</p>`;
 }catch(err){if(!active()||err.sessionExpired||err.staleSession||!body())return;body().innerHTML=`<div class="notice warning">${h(err.message)}</div>`;}
}
function changes(){shell(`<div class="heading"><div><div class="eyebrow">Change registry</div><h1>Changes</h1><p class="sub">Every change begins unassessed. Confidence must be earned by evidence.</p></div><button class="button primary" data-action="new-change" ${S.workspace.applications.length&&can('AUTHOR')?'':'disabled'}>+ New change</button></div>${note()}<section class="panel">${changeRows(S.workspace.changes)}</section>`,'changes','Changes');}
function changePage(){
 const c=S.change,a=S.workspace.applications.find(x=>x.id===c.applicationId),current=c.isCurrentRevision,canEdit=can('AUTHOR')&&current;
 const accepted=c.obligations.filter(o=>o.reviewStatus==='ACCEPTED').length,pending=c.obligations.filter(o=>o.reviewStatus==='IN_REVIEW').length;
 let detail='';
 if(S.tab==='overview')detail=`<section class="panel"><div class="panel-head"><h2>Declared change context</h2></div><div class="panel-body"><span class="field-label">Business intent</span><p>${h(c.intent||'Not supplied')}</p><div class="details"><div><span class="field-label">Source reference</span><div class="mono">${h(c.sourceRevision||'Not supplied')}</div><p class="small muted">Declared by a user; not independently bound to a deployed artifact.</p></div><div><span class="field-label">Producer</span>${h(c.producer)}</div><div><span class="field-label">Revision registered by</span>${h(c.revision.createdBy)}</div><div><span class="field-label">Reason</span>${h(c.revision.reason)}</div></div></div></section>`;
 if(S.tab==='overview'&&S.workspace.capabilities.githubIntake)detail+=sourceReceipts();
 if(S.tab==='obligations')detail=`<div class="grid"><section class="panel"><div class="panel-head"><div><h2>What needs to be established?</h2><p>${accepted} accepted · ${pending} awaiting review · ${c.obligations.length} total</p></div><div class="actions">${S.workspace.capabilities.obligationDrafting?`<a class="button" href="#/drafting/${h(c.id)}/${h(c.revision.id)}">${canEdit?'Draft from source':'View source drafts'}</a>`:''}<button class="button" data-action="new-obligation" ${canEdit?'':'disabled'}>+ Add obligation</button></div></div>${c.obligations.length?c.obligations.map(o=>{
 const own=[o.proposedBy,o.lastEditedBy].includes(S.session.email),reviewer=can('POLICY_AUTHORITY')&&current&&(!own||S.session.reviewMode==='founder-review');
 return `<article class="obligation" data-obligation-id="${h(o.id)}"><div class="obligation-top"><span class="field-label">OBL-${h(o.id.slice(0,8).toUpperCase())} · Version ${o.version}</span><button class="link-button" data-action="obligation-history" data-id="${h(o.id)}">Review history</button></div><h3>${h(o.statement)}</h3><div class="chip-row">${badge(reviewLabel(o.reviewStatus),o.reviewStatus==='ACCEPTED'?'accepted':o.reviewStatus==='CLARIFICATION_REQUIRED'?'clarify':o.reviewStatus==='REJECTED'?'rejected':'candidate')}${badge(o.authority)}${badge(o.state.replaceAll('_',' '),resultKind(o.state))}</div><div class="obligation-foot"><span><strong>Source:</strong> ${h(o.sourceReference||'Not supplied')}<br><strong>Source version:</strong> ${h(o.sourceVersion||'Not supplied')} · ${h(o.criticality)}</span><span>${o.evidenceCount??0} evidence ${o.evidenceCount===1?'item':'items'}</span></div><p class="small muted">${o.reviewStatus==='ACCEPTED'?'Accepted for this revision by a recorded human decision. This does not establish that the software satisfies it.':o.imported?'Imported candidate: review and save under a named identity before submission.':'Proposed by '+h(o.proposedBy)}</p><div class="actions obligation-actions">${canEdit&&o.reviewStatus!=='IN_REVIEW'?`<button class="button" data-action="edit-obligation" data-id="${h(o.id)}">${o.reviewStatus==='ACCEPTED'?'Revise requirement':'Edit draft'}</button>`:''}${canEdit&&['DRAFT','CLARIFICATION_REQUIRED'].includes(o.reviewStatus)?`<button class="button primary" data-action="review-submit" data-id="${h(o.id)}">Request review</button>`:''}${canEdit&&o.reviewStatus==='IN_REVIEW'&&own?`<button class="button" data-action="review-withdraw" data-id="${h(o.id)}">Withdraw request</button>`:''}${o.reviewStatus==='IN_REVIEW'&&current?reviewer?`<button class="button primary" data-action="review-decision" data-id="${h(o.id)}">Record decision</button>`:`<span class="small muted">${own?'Needs a different authorized reviewer.':'Awaiting a policy authority.'}</span>`:''}</div></article>`;}).join(''):`<div class="empty"><h3>No obligations for this revision</h3><p>Record an expectation and its source. It remains a candidate until reviewed.</p></div>`}</section><aside><div class="explanation"><h3>Acceptance is not verification.</h3><p>A policy authority confirms that this requirement applies to this revision.</p><p>The source, version, reason and decision-maker are retained. Software evidence is shown separately.</p><p><strong>Next:</strong> independent evidence must establish whether the requirement is satisfied.</p></div><div class="boundary-note"><span class="field-label">Review boundary</span><p>Revision ${c.revision.number}<br>${h(short(c.sourceRevision))}</p><p>Source references remain human declarations. No automatic source-authenticity claim.</p></div></aside></div>`;
 if(S.tab==='revisions')detail=`<section class="panel"><div class="panel-head"><div><h2>Change revisions</h2><p>Earlier revisions are read-only. Acceptance and evidence do not transfer automatically. Open a revision to inspect the decisions and evidence that belong to it.</p></div><button class="button primary" data-action="new-revision" ${can('AUTHOR')&&current?'':'disabled'}>+ New revision</button></div>${c.revisions.map(r=>`<div class="revision-row"><div><a href="#/changes/${h(c.id)}/revisions/${h(r.id)}"><strong>Revision ${r.number}</strong></a> ${r.id===c.currentRevisionId?badge('CURRENT'):badge('HISTORICAL')}<p class="mono">${h(r.sourceRevision||'Not supplied')}</p><p>${h(r.reason)}</p><p class="small muted">${h(r.createdBy)} · ${h(date(r.createdAt))}</p></div>${badge('SEPARATE ASSESSMENT')}</div>`).join('')}</section>`;
 if(S.tab==='evidence')detail=`<section class="panel"><div class="empty"><h2>No evidence collected</h2><p>Accepting a requirement is a human authority decision, not execution evidence. No verifier has run for this revision.</p>${badge('VERIFICATION NOT CONNECTED')}</div></section>`;
 if(S.tab==='history')detail=`<section class="panel"><div class="panel-head"><h2>Working activity</h2><p>This view filters the latest 100 workspace actions. Use each obligation’s Review history and each resolution’s history for its full recorded trail; an empty activity list does not mean earlier records were deleted.</p></div><div class="panel-body">${activityRows(S.workspace.activity.filter(x=>x.entityId===c.id||c.obligations.some(o=>o.id===x.entityId)))}</div></section>`;
 if(S.tab==='resolutions')detail=resolutionUI?.renderChange()??'<div class="notice">Resolution is not enabled on this deployment.</div>';
 if(S.tab==='assurance')detail=assurancePanel();
 if(S.tab==='evidence')detail=evidencePanel();
 shell(`<a class="back" href="#/changes">← Changes</a><div class="heading"><div><div class="eyebrow">${h(a?.name)} / Change</div><h1>${h(c.title)}</h1><p class="small muted">Revision ${c.revision.number} · <span class="mono">${h(short(c.sourceRevision))}</span> · Declared, not verified</p></div><div class="actions">${S.workspace.capabilities.revisionImpact?`<a class="button" href="#/impact/${h(c.id)}/${h(c.revision.id)}">Impact &amp; next checks</a>`:''}<button class="button" data-action="new-revision" ${canEdit?'':'disabled'}>+ New revision</button>${runButton()}</div></div>${!current?`<div class="notice warning"><strong>Historical revision · read-only</strong><span><a href="#/changes/${h(c.id)}">Open current revision →</a></span></div>`:''}${S.session.reviewMode==='founder-review'?'<div class="notice warning"><strong>Founder-review mode</strong><span>Same-person decisions are permitted and labelled. They do not establish independent approval.</span></div>':''}${assessmentBanner()}${nextStep()}<nav class="tabs" aria-label="Change sections">${['overview','obligations','assurance','evidence',...(S.workspace.capabilities.resolutionWorkflow?['resolutions']:[]),'revisions','history'].map(t=>`<button data-action="tab" data-tab="${t}" aria-current="${S.tab===t?'true':'false'}" class="${S.tab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</nav>${detail}`,'changes',c.title);
}
function activity(){shell(`<div class="heading"><div><div class="eyebrow">Workspace history</div><h1>Activity</h1><p class="sub">The latest 100 saved actions. These are working records, not certified assurance evidence.</p></div><a class="button" href="/api/export">Export records ↓</a></div><section class="panel"><div class="panel-body">${activityRows(S.workspace.activity)}</div></section>`,'activity','Activity');}
function errorPage(message){shell(`<section class="panel error-page"><h2>We could not open this view</h2><p role="alert">${h(message)}</p><div class="actions"><button class="button" data-action="retry">Try again</button><a class="button" href="#/overview">Open workspace</a><a class="button" href="#/support">Get support details</a></div><p class="small">If a save was interrupted, check the record before submitting the same action again.</p></section>`);}
let routeGeneration=0,pollTimer,dialogGeneration=0;
function viewContext(){const generation=routeGeneration,session=S.session,hash=location.hash;return()=>!!session&&generation===routeGeneration&&session===S.session&&hash===location.hash;}
function closeDialog(){++dialogGeneration;if(modal.open)modal.close();modal.replaceChildren();}
function pollAssessment(){pollTimer=setTimeout(()=>{if(modal.open||document.hidden)pollAssessment();else void route();},2500);}
async function route(){
 const generation=++routeGeneration;draftingUI?.invalidate();impactUI?.invalidate();templatesUI?.invalidate();resolutionUI?.invalidate();intakeUI?.invalidate();closeDialog();clearTimeout(pollTimer);if(!S.session)return login();
 try{
  const p=location.hash.replace(/^#\/?/,'').split('/');
  if(p[0]==='guide'){const ui=await ensureGuideUI();if(generation===routeGeneration)ui.showGuide();return;}
  if(p[0]==='support'){const ui=await ensureGuideUI();if(generation===routeGeneration)await ui.showSupport();return;}
  if(['verification-templates','template-save','template-plan'].includes(p[0])){
   if(!S.workspace.capabilities.verificationTemplates)return errorPage('Verification templates are not enabled in this workspace. Existing verification plans remain available.');
   const ui=await ensureTemplatesUI();if(generation!==routeGeneration)return;
   const validId=value=>typeof value==='string'&&/^[a-f0-9-]{36}$/i.test(value);
   const offset=value=>/^\d+$/.test(value??'')&&Number.isSafeInteger(Number(value))?Number(value):null;
   if(p[0]==='verification-templates'){
    if(p.length===1)return await ui.showList();
    if(p[1]==='page'&&[3,4].includes(p.length)&&offset(p[2])!==null&&(p.length===3||p[3]==='all'))return await ui.showList({offset:offset(p[2]),includeArchived:p[3]==='all'});
    if(validId(p[1])&&(p.length===2||p.length===4&&p[2]==='versions'&&validId(p[3])))return await ui.showDetail(p[1],p[3]??null);
   }else if(p[0]==='template-save'&&validId(p[1])&&validId(p[2])&&(p.length===3||p.length===4&&validId(p[3])))return await ui.showSave(p[1],p[2],p[3]??null);
   else if(p[0]==='template-plan'&&validId(p[1])&&validId(p[2])){
    if(p.length===3)return await ui.showList({changeId:p[1],revisionId:p[2]});
    if(p.length===5&&p[3]==='page'&&offset(p[4])!==null)return await ui.showList({changeId:p[1],revisionId:p[2],offset:offset(p[4])});
    if(p.length===5&&validId(p[3])&&validId(p[4]))return await ui.showPlan(p[1],p[2],p[3],p[4]);
   }
   return errorPage('This verification-template link is incomplete. Open a template from the saved list or a current verification plan.');
  }
  if(p[0]==='impact'){
   if(!S.workspace.capabilities.revisionImpact)return errorPage('Revision impact is not available in this workspace. Open the change to inspect its obligations and evidence.');
   if(p.length!==3||!p[1]||!p[2])return errorPage('This impact link is incomplete. Open Impact & next checks from the change.');
   const ui=await ensureImpactUI();if(generation!==routeGeneration)return;
   return await ui.show(p[1],p[2]);
  }
  if(p[0]==='drafting'){
   if(!S.workspace.capabilities.obligationDrafting)return errorPage('Source drafting is not enabled in this workspace. Manual obligation authoring remains available.');
   if(!p[1]||!p[2]||(p[3]&&!['runs','page'].includes(p[3]))||(p[3]&&!p[4])||p.length>5)return errorPage('This source-drafting link is incomplete. Open source drafts from the change.');
   const offset=p[3]==='page'?Number(p[4]):0;
   if(!Number.isSafeInteger(offset)||offset<0)return errorPage('The saved-draft page is invalid. Open source drafts from the change.');
   const ui=await ensureDraftingUI();if(generation!==routeGeneration)return;
   return await ui.show(p[1],p[2],{runId:p[3]==='runs'?p[4]:null,offset});
  }
  if(p[0]==='resolutions'&&S.workspace.capabilities.resolutionWorkflow){const ui=await ensureResolutionUI();if(generation!==routeGeneration)return;return p[1]?await ui.showItem(p[1]):await ui.showInbox();}
  if(p[0]==='intake'&&S.workspace.capabilities.githubIntake){const ui=await ensureIntakeUI();if(generation!==routeGeneration)return;return await ui.show(p[1]?decodeURIComponent(p[1]):null,p[2]?Number(p[2]):null);}
  if(p[0]==='applications')return p[1]?application(p[1]):applications();
  if(p[0]==='changes'){
   if(p[1]){
    const c=await api(`/api/changes/${encodeURIComponent(p[1])}${p[2]==='revisions'&&p[3]?'?revision='+encodeURIComponent(p[3]):''}`);
    if(generation!==routeGeneration)return;
    S.change=c;S.runs=[];S.assuranceContext=null;S.assuranceError=c.assuranceError?.message??null;S.resolutions=null;S.resolutionError=null;
    if(S.workspace.capabilities?.assessmentQueue){
     try{const [ctx,runs]=await Promise.all([api(`/api/changes/${c.id}/assurance-context?revision=${c.revision.id}`),api(`/api/changes/${c.id}/assessments?revision=${c.revision.id}`)]);
      if(generation!==routeGeneration)return;S.assuranceContext=ctx;S.runs=runs;S.assuranceError=null;
     }catch(e){if(e.status===401||e.staleSession)throw e;if(generation!==routeGeneration)return;S.assuranceError=e.message;}
    }
    if(S.workspace.capabilities.resolutionWorkflow){const ui=await ensureResolutionUI();await ui.loadChange();if(generation!==routeGeneration)return;}
    S.sources=[];S.sourceError=null;if(S.workspace.capabilities.githubIntake){try{const sources=await api(`/api/changes/${c.id}/source-imports`);if(generation!==routeGeneration)return;S.sources=sources;}catch(e){if(e.status===401||e.staleSession)throw e;if(generation!==routeGeneration)return;S.sourceError=e.message;}}
    changePage();
    if(S.runs.some(r=>['QUEUED','RUNNING'].includes(r.status)))pollAssessment();
    return;
   }return changes();
  }
  if(p[0]==='activity')return activity();return overview();
 }catch(e){if(e.staleSession||generation!==routeGeneration)return;if(e.status===401){clearSessionView();return login('Your session ended. Please sign in again.');}errorPage(e.message);}
}

function field(id,label,type='text',value='',hint='',required=false){return `<div class="form-field"><label for="${id}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="${id}" name="${id}" ${required?'required':''}>${h(value)}</textarea>`:`<input id="${id}" name="${id}" type="${type}" value="${h(value)}" ${required?'required':''}>`}${hint?`<small>${hint}</small>`:''}</div>`;}
function openForm(title,description,content,saveLabel,submit){
 const active=viewContext();closeDialog();
 modal.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div><div class="modal-body"><p class="small muted">${description}</p><form><div class="form-error" role="alert"></div>${content}<div class="form-actions"><button class="button" type="button" data-close>Cancel</button><button class="button primary" type="submit">${saveLabel}</button></div></form></div>`;
 modal.showModal();modal.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',closeDialog));
 const form=modal.querySelector('form'),present=()=>active()&&modal.open&&modal.querySelector('form')===form;
 let saving=false;
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(!present()||saving||!form.reportValidity())return;
  const data=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');
  const controls=[...form.elements],disabled=controls.map(control=>control.disabled);
  let saved=false;
  saving=true;controls.forEach(control=>control.disabled=true);button.textContent='Saving…';form.querySelector('.form-error').textContent='';
  try{
   const next=await submit(data);saved=true;if(!present())return;
   closeDialog();await refresh();if(!active())return;
   toast('Saved to your workspace.');
   if(typeof next==='string'&&next!==location.hash)location.hash=next;else await route();
  }catch(error){
   if(!active()||error.sessionExpired||error.staleSession)return;
   if(saved){toast('Your action was saved, but the workspace could not be refreshed. Reload the view to inspect the saved record.');return;}
   if(!present())return;
   form.querySelector('.form-error').textContent=error.status===409?error.message+' Close this dialog and reload the view before trying again.':error.message;
  }finally{
   saving=false;controls.forEach((control,index)=>control.disabled=disabled[index]);button.textContent=saveLabel;
  }
 });
}
function newApplication(){openForm('Register application','Create a saved record. This does not connect to the repository.',field('name','Application name','text','','For example: VendorPay',true)+field('description','Description','textarea','','What does this application do?')+field('repositoryUrl','Repository URL','url','','Optional HTTPS URL. Do not include credentials.'),'Register application',async d=>{const a=await api('/api/applications',{method:'POST',data:d});return `#/applications/${a.id}`;});}
function newChange(app=''){const active=viewContext();openForm('Create a change','Capture intent first. The change will remain unassessed.',`<div class="form-field"><label for="applicationId">Application *</label><select id="applicationId" name="applicationId" required>${S.workspace.applications.map(a=>`<option value="${h(a.id)}" ${app===a.id?'selected':''}>${h(a.name)}</option>`).join('')}</select></div>`+field('title','Change title','text','','What is being changed?',true)+field('intent','Business intent','textarea','','What outcome should this change achieve?')+field('sourceRevision','Source commit reference','text','','Optional 7–64 character Git hash. Recorded as declared, not verified.')+`<div class="form-field"><label for="producer">Producer category</label><select name="producer" id="producer"><option value="UNSPECIFIED">Not specified</option><option value="AI_ASSISTED">AI-assisted</option><option value="HUMAN">Human</option><option value="AUTOMATION">Automation</option></select></div>`,'Create change',async d=>{const c=await api('/api/changes',{method:'POST',data:d});if(active())S.tab='obligations';return `#/changes/${c.id}`;});}
function obligationForm(o){
 const changeId=S.change.id,revisionId=S.change.revision.id;
 const description=o?.reviewStatus==='ACCEPTED'?'Saving creates a new draft version. The prior acceptance remains in history and does not apply to the revised statement.':'Record the source and version. Submitting for review does not verify software behaviour.';
 openForm(o?'Revise obligation':'Propose an obligation',description,field('statement','What must be true?','textarea',o?.statement??'','One expectation that could be evaluated.',true)+field('sourceReference','Source reference','text',o?.sourceReference??'','Policy ID, requirement or document section.')+field('sourceVersion','Source version','text',o?.sourceVersion??'','For example: policy version 2 or an approved document revision.')+`<div class="form-field"><label for="criticality">Criticality</label><select id="criticality" name="criticality">${['LOW','MEDIUM','HIGH','CRITICAL'].map(x=>`<option ${x===(o?.criticality??'MEDIUM')?'selected':''}>${x}</option>`).join('')}</select></div>`,o?'Save new draft':'Add candidate',d=>o?api(`/api/obligations/${o.id}`,{method:'PATCH',data:{...d,version:o.version,revisionId}}):api(`/api/changes/${changeId}/obligations`,{method:'POST',data:{...d,revisionId}}));
}
function reviewForm(o,action){const revisionId=S.change.revision.id;const isDecision=action==='DECISION';const own=[o.proposedBy,o.lastEditedBy].includes(S.session.email);openForm(isDecision?'Record authority decision':action==='SUBMIT'?'Request review':'Withdraw review request',isDecision?'This decision concerns whether the requirement applies. It does not assess the software.':action==='SUBMIT'?'The submitted version will be locked while it is reviewed.':'Withdrawal reopens this candidate for editing.',`<div class="review-summary"><h3>${h(o.statement)}</h3><p>Source: ${h(o.sourceReference||'Not supplied')} · ${h(o.sourceVersion||'No version')}</p><p>Revision ${S.change.revision.number} · Obligation version ${o.version}</p></div>${isDecision?`<div class="form-field"><label for="action">Decision</label><select name="action" id="action"><option value="ACCEPT">Accept requirement</option><option value="REQUEST_CLARIFICATION">Request clarification</option><option value="REJECT">Reject candidate</option></select></div>${own?'<div class="notice warning">Same-person decision: no independent approval is claimed.</div>':''}${field('rationale','Reason for this decision','textarea','','At least 10 characters. Explain the source and applicability.',true)}`:''}`,isDecision?'Save decision':action==='SUBMIT'?'Submit for review':'Withdraw',d=>api(`/api/obligations/${o.id}/review`,{method:'POST',data:{...d,action:isDecision?d.action:action,version:o.version,revisionId}}));}
function newRevision(){const c=S.change,active=viewContext();openForm('Register a new revision','The previous revision and its decisions remain read-only. This does not fetch or verify source code.',field('sourceRevision','New source commit reference','text','','A different Git reference, recorded as declared.',true)+field('intent','Business intent','textarea',c.intent,'What should this revision achieve?',true)+field('reason','What changed and why?','textarea','','Explain the reason for the new revision.',true)+`<div class="form-field"><label for="copyObligations">Prior obligations</label><select name="copyObligations" id="copyObligations"><option value="true">Copy non-rejected obligations as new candidates</option><option value="false">Start with no obligations</option></select><small>Copied obligations require new review. No acceptance, evidence or disposition transfers.</small></div>`,'Create revision',async d=>{const next=await api(`/api/changes/${c.id}/revisions`,{method:'POST',data:{...d,copyObligations:d.copyObligations==='true',expectedRevisionId:c.currentRevisionId}});if(active())S.tab='obligations';return `#/changes/${next.id}`;});}
async function showObligationHistory(o){const active=viewContext(),dialog=++dialogGeneration,events=await api(`/api/obligations/${o.id}/history`);if(!active()||dialog!==dialogGeneration)return;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">Obligation review history</h2><button class="close" data-close aria-label="Close dialog">×</button></div><div class="modal-body"><p class="small muted">Append-only application history, not tamper-proof evidence. Earlier content is retained.</p>${events.slice().reverse().map(e=>`<article class="decision-card"><div class="chip-row">${badge(e.action.replaceAll('_',' '),'candidate')}${badge('VERSION '+e.version)}</div><p class="decision-actor">${h(e.actor)} · ${h(date(e.createdAt))}</p><p>${h(e.rationale||'Candidate recorded.')}</p>${['ACCEPT','REJECT','REQUEST_CLARIFICATION'].includes(e.action)?`<p class="small muted">${e.independentActor?'Different recorded reviewer identity. This is not a guarantee of organizational independence.':'No independent-review claim.'}</p>`:''}<details><summary>Content at this decision</summary><p>${h(e.snapshot.statement)}</p><p class="small">Source: ${h(e.snapshot.sourceReference??'')} · ${h(e.snapshot.sourceVersion??'')}</p><p class="small">Review state: ${h(e.snapshot.reviewStatus)}</p></details></article>`).join('')}</div>`;modal.showModal();modal.querySelector('[data-close]').onclick=closeDialog;}
function resultKind(value){return ['NOT_READY','VIOLATED'].includes(value)?'finding-bad':['READY','SUPPORTED'].includes(value)?'finding-good':['INDETERMINATE','INSUFFICIENT'].includes(value)?'finding-gap':'';}
function runButton(){const ctx=S.assuranceContext,active=S.runs.some(r=>['QUEUED','RUNNING'].includes(r.status));const enabled=S.change.isCurrentRevision&&ctx?.plan?.current&&!active&&(can('AUTHOR')||can('POLICY_AUTHORITY'));return `<button class="button primary" data-action="run-assurance" ${enabled?'':'disabled'} title="Requires a current authority-approved plan and a separately running worker">${active?'Assessment in progress':'Run assurance'}</button>`;}
function assessmentBanner(){
 const latest=S.runs[0],current=latest&&latest.applicability==='CURRENT';
 let title='Not assessed',copy='No assessment has completed for these inputs.',kind='';
 if(S.assuranceError){title='Assessment information unavailable';copy='No readiness claim can be made from this view. Reload or contact the deployment owner.';}
 else if(latest){
  if(latest.applicability==='STALE_INPUTS'){title='Reassessment required';copy='Earlier evidence belongs to different obligations, a plan, or target configuration. It remains in history.';}
  else if(latest.applicability==='HISTORICAL_REVISION'){title='Historical assessment';copy='This record applies to the selected earlier revision, not the current change.';}
  else if(latest.status==='QUEUED'){title='Queued';copy='Waiting for the separate assurance worker. No disposition has been issued.';}
  else if(latest.status==='RUNNING'){title='Running';copy='Executing the approved checks and their positive controls. No disposition is available until completion.';}
  else if(latest.status==='COMPLETED'&&latest.disposition){title=latest.disposition.replaceAll('_',' ');copy=latest.case.reason;kind=resultKind(latest.disposition);}
  else {title=latest.status==='COMPLETED'?'Evidence integrity unresolved':latest.status.replaceAll('_',' ');copy='No disposition is available. '+findingReason(latest.failureCode??latest.evidenceIntegrity??'');}
 }
 return `<section class="status-panel ${kind}"><div><span class="field-label">${current?'Current assessment':'Assessment status'}</span><h2>${h(title)}</h2><p>${h(copy)}</p><p class="small">Scope-bound behavioural assessment. Not universal safety or release certification.</p></div><div class="chip-row">${badge(S.change.obligations.filter(o=>o.reviewStatus==='ACCEPTED').length+' ACCEPTED')}${latest?badge(latest.status):''}</div></section>`;
}
function assurancePanel(){const ctx=S.assuranceContext;
 if(!ctx)return `<section class="panel"><div class="empty"><h2>Assurance setup is not available</h2><p>${h(S.assuranceError??'The deployment owner must enable the protected target catalogue and separate worker. Requirement review remains available.')}</p></div></section>`;
 const plan=ctx.plan,required=ctx.scope.obligations.filter(o=>o.reviewStatus!=='REJECTED');
 return `<div class="grid"><section class="panel"><div class="panel-head"><div><h2>Approved verification plan</h2><p>Explicit supported mappings. Every non-rejected obligation stays in scope.</p></div><button class="button" data-action="configure-plan" ${can('POLICY_AUTHORITY')&&ctx.isCurrent&&ctx.targets.length?'':'disabled'}>${plan?'Revise mapping':'Configure mapping'}</button></div><div class="panel-body">${plan?`${badge(plan.current?'CURRENT PLAN':'STALE PLAN',plan.current?'candidate':'finding-gap')}<h3>${h(plan.snapshot.profile.title)}</h3>${mappingsOf(plan.snapshot).map(m=>`<article class="run-card"><strong>${h(m.checkId??"separation")}</strong><p>${h(ctx.scope.obligations.find(o=>o.id===m.obligationId)?.statement??m.obligationId)}</p><p class="small">${h(m.rationale)}</p></article>`).join('')}<p class="small">Approved by ${h(plan.approvedBy)} · Plan ${plan.version}</p><div class="detail-value">Target: ${h(plan.snapshot.target.name)}</div><p class="small mono">${h(plan.snapshot.target.sourceRevision)}</p>`:`<h3>No mapping has been accepted</h3><p>A Policy Authority must confirm which accepted obligation this verifier supports. Merely choosing a test does not establish coverage.</p>${ctx.targets.length?'':'<div class="notice warning">No configured target matches this application and full source revision. Ask the deployment owner to register the test target.</div>'}`}
 ${S.workspace.capabilities.verificationTemplates?`<div class="actions template-plan-actions">${ctx.isCurrent?`<a class="button" href="#/template-plan/${h(S.change.id)}/${h(S.change.revision.id)}">Use a template</a>`:''}${can('POLICY_AUTHORITY')&&ctx.isCurrent&&plan?.current&&plan.snapshot.schema==='qivvera.assurance-plan/2'?`<a class="button" href="#/template-save/${h(S.change.id)}/${h(S.change.revision.id)}">Save as template</a>`:''}<a class="button" href="#/verification-templates">Browse templates</a></div>`:''}
 ${plan?.templateUse?`<div class="review-summary template-use-receipt"><h3>Template reference</h3><a href="#/verification-templates/${h(plan.templateUse.templateId)}/versions/${h(plan.templateUse.versionId)}">${h(plan.templateUse.name)} · Version ${h(plan.templateUse.version)}</a><p class="small">Fresh plan approved by ${h(plan.templateUse.usedBy)} · ${h(date(plan.templateUse.usedAt))}. No prior evidence or approval transfers.</p></div>`:''}
 <div class="inline-note">${required.length} required obligation(s). Unaccepted or unmapped obligations produce visible gaps; they are not silently omitted.</div>
 <h3>Declared limitations</h3><p class="small">${h(ctx.profile.exclusions.join(' · '))}</p><p class="small">Target identity is operator-pinned and target-reported, not independently attested.</p></div></section>
 <aside class="panel"><div class="panel-head"><h2>Assessment runs</h2><button class="link-button" data-action="refresh-assurance">Refresh</button></div><div class="panel-body">${S.runs.length?S.runs.map(r=>`<article class="run-card"><div class="chip-row">${badge(r.status)}${r.disposition?badge(r.disposition.replaceAll('_',' '),resultKind(r.disposition)):''}</div><p class="small">${h(date(r.queuedAt))}</p><p class="small">${h(r.applicability.replaceAll('_',' '))}</p><button class="link-button" data-action="open-assessment" data-id="${h(r.id)}">Open assurance case →</button>${['QUEUED','RUNNING'].includes(r.status)&&(can('AUTHOR')||can('POLICY_AUTHORITY'))?`<button class="link-button" data-action="cancel-assessment" data-id="${h(r.id)}">Cancel acceptance</button>`:''}</article>`).join(''):'<p>No assessment requested. A run will appear here only after an Author or Policy Authority requests one using the current approved plan.</p>'}</div></aside></div>`;
}
function evidencePanel(){const runs=S.runs.filter(r=>r.evidence||r.evidenceIntegrity==='DIGEST_MISMATCH');return `<section class="panel"><div class="panel-head"><div><h2>Execution evidence</h2><p>Actual observations, tied to a frozen revision, scope, target, and verifier.</p></div></div><div class="panel-body">${runs.length?runs.map(r=>`<article class="run-card"><div class="chip-row">${badge(r.evidenceIntegrity)}${badge(r.applicability)}${r.evidence?badge(r.evidence.report.outcome??'MULTIPLE FINDINGS',resultKind(r.evidence.report.outcome)):''}</div><p>${h(findingReason(r.evidence?.report.reason??(r.evidence?.report.reports?'Inspect the evidence for each mapped obligation.':null)??'Evidence failed its content-digest check. No disposition is accepted.'))}</p><p class="small mono">${h(r.evidenceDigest??'')}</p><button class="button" data-action="open-assessment" data-id="${h(r.id)}">Inspect expected vs observed</button></article>`).join(''):'<div class="empty"><h3>No execution evidence yet</h3><p>Accepted requirements and saved plans are not execution evidence.</p></div>'}</div></section>`;}

function configureMultiPlan(ctx,accepted){
 const changeId=ctx.scope.changeId,revisionId=ctx.scope.revisionId;
 const mappingFields=ctx.checks.map(check=>`<fieldset><legend>${h(check.title)}</legend><p class="small">${h(check.rule)}</p><div class="form-field"><label for="map_${h(check.id)}">Accepted obligation to verify</label><select id="map_${h(check.id)}" name="map_${h(check.id)}"><option value="">Not mapped — any related mandatory obligation remains a gap</option>${accepted.map(o=>`<option value="${h(o.id)}">${h(o.statement)}</option>`).join('')}</select></div>${field('reason_'+check.id,'Why does this check support the requirement?','textarea','','Required when mapped; at least 10 characters.')}</fieldset>`).join('');
 openForm('Approve verification plan','One or two supported checks. Each needs a distinct accepted obligation; unmapped obligations cannot become supported.',`<div class="form-field"><label for="targetId">Approved test target</label><select name="targetId" id="targetId">${ctx.targets.map(t=>`<option value="${h(t.id)}">${h(t.name)} · ${h(t.adapterId??'approval-v1')}</option>`).join('')}</select></div>${mappingFields}${field('rationale','Plan rationale','textarea','','Explain the selected scope and limitations.',true)}<label class="acknowledge"><input type="checkbox" name="acknowledgeLimits" required> I acknowledge the exact contracts, exclusions and target-binding limitations.</label>`,'Approve plan',d=>api(`/api/changes/${changeId}/assurance-plan`,{method:'POST',data:{revisionId,scopeDigest:ctx.scopeDigest,expectedPlanVersion:ctx.plan?.version??0,targetId:d.targetId,rationale:d.rationale,acknowledgeLimits:d.acknowledgeLimits==='on',mappings:ctx.checks.filter(c=>d['map_'+c.id]).map(c=>({checkId:c.id,obligationId:d['map_'+c.id],rationale:d['reason_'+c.id]}))}}));
}

function configurePlan(){const changeId=S.change.id,revisionId=S.change.revision.id,ctx=S.assuranceContext,accepted=S.change.obligations.filter(o=>o.reviewStatus==='ACCEPTED');if(!accepted.length)return toast('Accept an obligation before mapping a verifier.');if(ctx.checks?.length)return configureMultiPlan(ctx,accepted);
 openForm('Approve verification mapping','This is an authority decision about coverage. The check writes isolated synthetic requests to an operator-approved test application.',`<div class="form-field"><label for="obligationId">Accepted obligation</label><select id="obligationId" name="obligationId">${accepted.map(o=>`<option value="${h(o.id)}">${h(o.statement)}</option>`).join('')}</select></div><div class="form-field"><label for="targetId">Approved test target</label><select id="targetId" name="targetId">${ctx.targets.map(t=>`<option value="${h(t.id)}">${h(t.name)}</option>`).join('')}</select></div><div class="review-summary"><h3>What this verifier actually establishes</h3><p>${h(ctx.profile.rule)}</p><p class="small">Only the described interface and identities are exercised. Every other non-rejected obligation remains mandatory and will be reported as a gap if unsupported.</p></div>${field('rationale','Why does this check support the obligation?','textarea','','Explain the mapping and accepted limitations; at least 10 characters.',true)}<label class="acknowledge"><input type="checkbox" name="acknowledgeLimits" required> I accept this declared scope and its limitations. The target binding is not an independent build attestation.</label>`,'Approve plan',d=>api(`/api/changes/${changeId}/assurance-plan`,{method:'POST',data:{...d,acknowledgeLimits:d.acknowledgeLimits==='on',revisionId,scopeDigest:ctx.scopeDigest,expectedPlanVersion:ctx.plan?.version??0}}));
}
function requestAssessment(){const active=viewContext(),changeId=S.change.id,revisionId=S.change.revision.id,ctx=S.assuranceContext,key=crypto.randomUUID();if(!ctx?.plan?.current)return;openForm('Request assurance','A separate worker will execute the accepted plan. This does not run inside the browser or claim an immediate result.',`<div class="review-summary"><p>Target: ${h(ctx.plan.snapshot.target.name)}</p><p>Revision: <span class="mono">${h(S.change.sourceRevision)}</span></p><p>Only synthetic operations in the configured test environment are authorized.</p></div>`,'Queue assessment',async()=>{await api(`/api/changes/${changeId}/assessments`,{method:'POST',data:{revisionId,planId:ctx.plan.id,requestKey:key}});if(active())S.tab='assurance';});}
async function showAssessment(id){const active=viewContext(),dialog=++dialogGeneration,r=await api(`/api/assessments/${id}`);if(!active()||dialog!==dialogGeneration)return;const s=r.snapshot,rawReport=r.evidence?.report,report=rawReport?.reports?{observations:rawReport.reports.flatMap(x=>x.report.observations.map(o=>({...o,step:x.checkId+' · '+x.obligationId.slice(0,8)+' · '+o.step})))}:rawReport;
 modal.innerHTML=`<div class="modal-head"><div><span class="eyebrow">Scope-bound assurance case</span><h2 id="modal-title">${h(r.disposition?.replaceAll('_',' ')??r.status.replaceAll('_',' '))}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div><div class="modal-body assurance-case"><div class="chip-row">${badge(r.applicability)}${badge(r.evidenceIntegrity)}</div><p>${h(findingReason(r.case?.reason??r.failureCode??'The worker has not produced a complete accepted result.'))}</p><div class="notice"><span>Readiness applies only to the frozen declared scope. Not universal safety, compliance, or an attested software supply chain.</span></div><h3>Obligations and gaps</h3>${(r.case?.findings??[]).map(f=>`<article class="run-card">${badge(f.state,resultKind(f.state))}<h4>${h(f.statement)}</h4><p class="small">${h(findingReason(f.reason))}</p></article>`).join('')}${r.evidence?.counterevidence?.length?`<h3>Unresolved contrary evidence</h3><div class="notice warning">A later passing execution cannot erase an earlier valid counterexample for these inputs.</div>${r.evidence.counterevidence.map(e=>`<p class="small">Run ${h(e.runId)} · ${h(findingReason(e.reason))}<br><span class="mono">${h(e.evidenceDigest)}</span></p>`).join('')}`:''}${resolutionUI?`<div class="actions resolution-source">${resolutionUI.sourceButtons(r)}</div>`:''}<h3>Expected versus observed</h3>${(report?.observations??[]).map(o=>`<details class="observation"><summary>${h(o.step)}</summary><div class="observation-grid"><div><span class="field-label">Expected</span><pre>${h(JSON.stringify(o.expected,null,2))}</pre></div><div><span class="field-label">Observed</span><pre>${h(JSON.stringify(o.observed,null,2))}</pre></div></div></details>`).join('')||'<p>No observations available.</p>'}<h3>Assurance boundary</h3><dl class="boundary"><dt>Source revision</dt><dd>${h(s.target.sourceRevision)}</dd><dt>Artifact digest</dt><dd>${h(s.target.artifactDigest)}</dd><dt>Environment digest</dt><dd>${h(s.target.environmentDigest)}</dd><dt>Instance</dt><dd>${h(s.target.instanceId)}</dd><dt>Scope digest</dt><dd>${h(s.scopeDigest)}</dd><dt>Profile</dt><dd>${h(s.profile.id)} / ${h(s.profile.version)}</dd><dt>Verifier digest</dt><dd>${h(s.verifier?.digest??s.mappings.map(m=>m.checkId+": "+m.verifier.digest).join("; "))}</dd><dt>Worker</dt><dd>${h(r.workerId??'Not yet claimed')}</dd><dt>Evidence cutoff</dt><dd>${h(r.finishedAt??'Not completed')}</dd><dt>Excluded areas</dt><dd>${h(s.profile.exclusions.join('; '))}</dd><dt>Binding limitation</dt><dd>${h(s.profile.independence.binding)}</dd><dt>Integrity limitation</dt><dd>${h(s.profile.independence.evidence)}</dd></dl><a class="button" href="/api/assessments/${h(r.id)}/export">Export case JSON</a></div>`;
 modal.showModal();modal.querySelector('[data-close]').onclick=closeDialog;
}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-resolution]');if(!b||renderedGeneration!==routeGeneration&&b.dataset.action!=='logout')return;const active=viewContext();try{if(b.dataset.resolution){await resolutionUI?.handle(b);return;}switch(b.dataset.action){case 'configure-plan':configurePlan();break;case 'run-assurance':requestAssessment();break;case 'refresh-assurance':await route();break;case 'refresh-pulls':{const id=location.hash.split('/')[2];if(id)await loadPulls(decodeURIComponent(id));break;}case 'refresh-events':{const id=location.hash.split('/')[2];if(id)await loadSourceEvents(decodeURIComponent(id));break;};case 'open-assessment':await showAssessment(b.dataset.id);break;case 'cancel-assessment':await api(`/api/assessments/${b.dataset.id}/cancel`,{method:'POST',data:{}});if(active())await route();break;case 'logout':clearTimeout(pollTimer);await api('/api/session',{method:'DELETE'});clearSessionView();login();break;case 'new-application':newApplication();break;case 'new-change':newChange(b.dataset.app);break;case 'new-revision':newRevision();break;case 'review-submit':reviewForm(S.change.obligations.find(o=>o.id===b.dataset.id),'SUBMIT');break;case 'review-withdraw':reviewForm(S.change.obligations.find(o=>o.id===b.dataset.id),'WITHDRAW');break;case 'review-decision':reviewForm(S.change.obligations.find(o=>o.id===b.dataset.id),'DECISION');break;case 'obligation-history':await showObligationHistory(S.change.obligations.find(o=>o.id===b.dataset.id));break;case 'new-obligation':obligationForm();break;case 'edit-obligation':obligationForm(S.change.obligations.find(o=>o.id===b.dataset.id));break;case 'tab':S.tab=b.dataset.tab;changePage();break;case 'retry':if(S.session){await refresh();if(active())await route();}else await bootstrap();break;}}catch(err){if((active()||b.dataset.action==='logout')&&!err.sessionExpired&&!err.staleSession)toast(err.message);}});
modal.addEventListener('click',async e=>{const b=e.target.closest('[data-resolution]');if(!b)return;try{await resolutionUI?.handle(b);}catch(err){if(!err.sessionExpired&&!err.staleSession)toast(err.message);}});
modal.addEventListener('cancel',()=>{++dialogGeneration;});
window.addEventListener('hashchange',route);
async function bootstrap(){
 try{S.session=await api('/api/session');await refresh();await route();}
 catch(e){
  if(e.sessionExpired||e.staleSession)return;
  if(e.status===401){clearSessionView();login();return;}
  if(S.session){errorPage(e.message);return;}
  root.innerHTML=`<main id="main" class="main"><section class="panel error-page"><h1>Qivvera could not be opened</h1><p role="alert">${h(e.message)}</p><button class="button primary" data-action="retry">Try again</button><p class="small">Your workspace operator can investigate if the service remains unavailable. No sign-in attempt was submitted.</p></section></main>`;
 }
}
await bootstrap();

function sourceReceipts(){
 const receipts=(S.sources??[]).filter(r=>r.revisionId===S.change.revision.id);
 if(S.sourceError)return `<div class="notice warning">${h(S.sourceError)}</div>`;
 return `<section class="panel resolution-source"><div class="panel-head"><h2>Imported source context</h2></div><div class="panel-body">${receipts.length?receipts.map(r=>`<article class="run-card"><a href="${h(r.source.url)}" rel="noreferrer" target="_blank">${h(r.source.repository)} #${h(r.source.pullNumber)}</a><p>${h(r.source.title)}</p><p class="mono">${h(r.source.headSha)}</p><p class="small">Imported by ${h(r.importedBy)} · ${h(date(r.importedAt))}</p><p class="small">Provider-observed head at import time. Not proof of a deployed binary, requirement acceptance or readiness.</p></article>`).join(''):'<p>No GitHub import is attached to this revision. A manually declared source reference is not a provider-observed receipt.</p>'}</div></section>`;
}
